export const DEAL_STAGES = [
  'lead',
  'qualified',
  'active',
  'negotiation',
  'closed_won',
  'closed_lost',
] as const;

export type DealStage = (typeof DEAL_STAGES)[number];

export const DEAL_INITIAL_STAGES: DealStage[] = ['lead', 'qualified'];

export const DEAL_STAGE_TRANSITIONS: Record<DealStage, DealStage[]> = {
  lead: ['qualified', 'closed_lost'],
  qualified: ['active', 'closed_lost'],
  active: ['negotiation', 'closed_lost'],
  negotiation: ['closed_won', 'closed_lost'],
  closed_won: [],
  closed_lost: ['lead'],
};

const CANONICAL_STAGE_SET = new Set<string>(DEAL_STAGES);

const LEGACY_STAGE_ALIASES: Record<string, DealStage> = {
  won: 'closed_won',
  lost: 'closed_lost',
  prospect: 'lead',
  proposal_sent: 'negotiation',
};

function normalizeStageValue(value: string | null | undefined) {
  if (typeof value !== 'string') {
    return '';
  }

  return value.trim().toLowerCase();
}

export function parseRequestedDealStage(
  value: string | null | undefined,
): DealStage | null {
  const normalized = normalizeStageValue(value);

  if (!normalized || !CANONICAL_STAGE_SET.has(normalized)) {
    return null;
  }

  return normalized as DealStage;
}

export function normalizeStoredDealStage(
  value: string | null | undefined,
): DealStage {
  const normalized = normalizeStageValue(value);

  if (CANONICAL_STAGE_SET.has(normalized)) {
    return normalized as DealStage;
  }

  return LEGACY_STAGE_ALIASES[normalized] ?? 'lead';
}
