@Entity('deals')
export class DealEntity {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ type: 'varchar', length: 255, comment: 'Deal Name' })
  name!: string;

  @Column({
    type: 'double precision',
    comment: 'Deal Monetary Value',
  })
  value!: number;

  @Column({
    type: 'varchar',
    length: 100,
    default: 'lead',
    comment: 'Pipeline Stage',
  })
  stage!: string;

  @Column({ type: 'uuid', comment: 'Linked Company ID' })
  companyId!: string;

  @Column({
    type: 'uuid',
    nullable: true,
    comment: 'Primary Contact ID for display',
  })
  primaryContactId!: string | null;

  @Column({
    type: 'date',
    nullable: true,
    comment: 'Expected Close Date',
  })
  expectedCloseDate!: string | null;

  @CreateDateColumn({ type: 'timestamptz', comment: 'Creation Timestamp' })
  createdAt!: Date;

  @UpdateDateColumn({ type: 'timestamptz', comment: 'Update Timestamp' })
  updatedAt!: Date;

  contactLinks?: Array<{
    contactId: string;
    role: string | null;
  }>;

  company?: {
    id: string;
    name: string;
  };
}
