import { HttpStatus, Injectable } from '@nestjs/common';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from '../company/company.module';
import { ContactService } from '../contact/contact.module';
import {
  CreateDealDto,
  DealListQueryDto,
  TransitionDealStageDto,
  UpdateDealDto,
} from './dto';
import { DealContactLinkEntity } from './deal-contact-link.entity';
import { DealContactLinkRepository } from './deal-contact-link.repository';
import { DealEntity } from './deal.entity';
import { DealRepository } from './deal.repository';
import {
  DEAL_INITIAL_STAGES,
  DEAL_STAGE_TRANSITIONS,
  DealStage,
  normalizeStoredDealStage,
  parseRequestedDealStage,
} from './deal-stage';

type DealContactLinkInput = {
  contactId: string;
  role?: string | null;
};

type StageTransitionResult = {
  targetStage: DealStage;
  shouldPersist: boolean;
};

@Injectable()
export class DealService {
  constructor(
    private readonly dealRepository: DealRepository,
    private readonly dealContactLinkRepository: DealContactLinkRepository,
    private readonly companyService: CompanyService,
    private readonly contactService: ContactService,
  ) {}

  async createDeal(dto: CreateDealDto): Promise<DealEntity> {
    await this.ensureCompanyExists(dto.companyId);

    const initialStage = this.resolveInitialStage(dto.stage);

    const normalizedLinks = this.normalizeContactLinks(dto.contactLinks ?? []);
    await this.ensureContactsExist(
      normalizedLinks.map((link) => link.contactId),
    );

    const resolvedPrimaryContactId = this.resolvePrimaryContactId({
      links: normalizedLinks,
      preferredPrimaryContactId: dto.primaryContactId ?? null,
      fallbackPrimaryContactId: null,
    });

    this.ensurePrimaryContactInLinks(resolvedPrimaryContactId, normalizedLinks);

    const createdDeal = await this.dealRepository.manager.transaction(
      async (manager) => {
        const deal = await manager.getRepository(DealEntity).save(
          manager.getRepository(DealEntity).create({
            name: dto.name,
            value: dto.value,
            stage: initialStage,
            companyId: dto.companyId,
            expectedCloseDate: dto.expectedCloseDate ?? null,
            primaryContactId: resolvedPrimaryContactId,
          }),
        );

        if (normalizedLinks.length > 0) {
          await manager.getRepository(DealContactLinkEntity).save(
            normalizedLinks.map((link) =>
              manager.getRepository(DealContactLinkEntity).create({
                dealId: deal.id,
                contactId: link.contactId,
                role: link.role ?? null,
              }),
            ),
          );
        }

        return deal;
      },
    );

    return this.getDealWithLinks(createdDeal.id, false);
  }

  async getDeals(query: DealListQueryDto) {
    const stageFilter =
      query.stage === undefined
        ? undefined
        : this.parseRequestedStageOrThrow(query.stage);

    const list = await this.dealRepository.findWithFilter({
      ...query,
      stage: stageFilter,
    });

    return {
      ...list,
      items: list.items.map((item) => this.withCanonicalStage(item)),
    };
  }

  async getDealById(id: string) {
    return this.getDealWithLinks(id, true);
  }

  async updateDeal(id: string, dto: UpdateDealDto): Promise<DealEntity> {
    if (Object.keys(dto).length === 0) {
      throw this.createValidationException(
        'body',
        'At least one mutable field is required.',
      );
    }

    const deal = await this.getExistingDeal(id);
    const existingLinks = await this.dealContactLinkRepository.findByDealId(id);

    const hasIncomingLinks = dto.contactLinks !== undefined;
    const normalizedLinks = hasIncomingLinks
      ? this.normalizeContactLinks(dto.contactLinks ?? [])
      : existingLinks;

    if (hasIncomingLinks) {
      await this.ensureContactsExist(
        normalizedLinks.map((link) => link.contactId),
      );
    }

    const resolvedPrimaryContactId = this.resolvePrimaryContactId({
      links: normalizedLinks,
      preferredPrimaryContactId:
        dto.primaryContactId === undefined ? undefined : dto.primaryContactId,
      fallbackPrimaryContactId: deal.primaryContactId,
    });

    this.ensurePrimaryContactInLinks(resolvedPrimaryContactId, normalizedLinks);

    const stageTransition =
      dto.stage === undefined
        ? undefined
        : this.resolveStageTransition({
            currentStage: normalizeStoredDealStage(deal.stage),
            requestedStageValue: dto.stage,
            linkedContactCount: normalizedLinks.length,
            expectedCloseDate:
              dto.expectedCloseDate === undefined
                ? deal.expectedCloseDate
                : dto.expectedCloseDate,
          });

    await this.dealRepository.manager.transaction(async (manager) => {
      const mergedDeal = manager.getRepository(DealEntity).merge(deal, {
        name: dto.name,
        value: dto.value,
        stage:
          stageTransition?.shouldPersist === true
            ? stageTransition.targetStage
            : undefined,
        expectedCloseDate: dto.expectedCloseDate,
        primaryContactId: resolvedPrimaryContactId,
      });

      await manager.getRepository(DealEntity).save(mergedDeal);

      if (hasIncomingLinks) {
        await manager
          .getRepository(DealContactLinkEntity)
          .delete({ dealId: id });

        if (normalizedLinks.length > 0) {
          await manager.getRepository(DealContactLinkEntity).save(
            normalizedLinks.map((link) =>
              manager.getRepository(DealContactLinkEntity).create({
                dealId: id,
                contactId: link.contactId,
                role: link.role ?? null,
              }),
            ),
          );
        }
      }
    });

    return this.getDealWithLinks(id, false);
  }

  async transitionDealStage(
    id: string,
    dto: TransitionDealStageDto,
  ): Promise<DealEntity> {
    const deal = await this.getExistingDeal(id);
    const existingLinks = await this.dealContactLinkRepository.findByDealId(id);
    const stageTransition = this.resolveStageTransition({
      currentStage: normalizeStoredDealStage(deal.stage),
      requestedStageValue: dto.stage,
      linkedContactCount: existingLinks.length,
      expectedCloseDate: deal.expectedCloseDate,
    });

    if (stageTransition.shouldPersist) {
      const mergedDeal = this.dealRepository.merge(deal, {
        stage: stageTransition.targetStage,
      });

      await this.dealRepository.save(mergedDeal);
    }

    return this.getDealWithLinks(id, false);
  }

  private async getDealWithLinks(id: string, includeCompanySummary: boolean) {
    const deal = await this.getExistingDeal(id);
    const contactLinks = await this.dealContactLinkRepository.findByDealId(id);
    const dealWithCanonicalStage = this.withCanonicalStage(deal);

    if (!includeCompanySummary) {
      return {
        ...dealWithCanonicalStage,
        contactLinks,
      };
    }

    const company = await this.companyService.getCompanyById(deal.companyId);

    return {
      ...dealWithCanonicalStage,
      contactLinks,
      company: {
        id: company.id,
        name: company.name,
      },
    };
  }

  private async getExistingDeal(id: string) {
    const deal = await this.dealRepository.findOne({ where: { id } });

    if (!deal) {
      throw this.createNotFoundException('Deal', id);
    }

    return deal;
  }

  private normalizeContactLinks(contactLinks: DealContactLinkInput[]) {
    const deduplicated = new Map<
      string,
      { contactId: string; role: string | null }
    >();

    for (const link of contactLinks) {
      if (deduplicated.has(link.contactId)) {
        throw this.createValidationException(
          'contactLinks',
          'Duplicate contact links are not allowed.',
        );
      }

      deduplicated.set(link.contactId, {
        contactId: link.contactId,
        role: link.role?.trim() ? link.role.trim() : null,
      });
    }

    return [...deduplicated.values()];
  }

  private resolvePrimaryContactId({
    links,
    preferredPrimaryContactId,
    fallbackPrimaryContactId,
  }: {
    links: Array<{ contactId: string; role: string | null }>;
    preferredPrimaryContactId: string | null | undefined;
    fallbackPrimaryContactId: string | null;
  }) {
    if (preferredPrimaryContactId !== undefined) {
      return preferredPrimaryContactId;
    }

    if (
      fallbackPrimaryContactId &&
      links.some((link) => link.contactId === fallbackPrimaryContactId)
    ) {
      return fallbackPrimaryContactId;
    }

    if (links.length === 1) {
      return links[0].contactId;
    }

    return null;
  }

  private ensurePrimaryContactInLinks(
    primaryContactId: string | null,
    links: Array<{ contactId: string }>,
  ) {
    if (primaryContactId === null) {
      return;
    }

    const hasPrimaryContact = links.some(
      (link) => link.contactId === primaryContactId,
    );

    if (!hasPrimaryContact) {
      throw this.createValidationException(
        'primaryContactId',
        'primaryContactId must be included in contactLinks.',
      );
    }
  }
import {
  Body,
  Controller,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Post,
  Query,
} from '@nestjs/common';
import { DealService } from './deal.service';
import {
  CreateDealDto,
  DealIdParamDto,
  DealListQueryDto,
  TransitionDealStageDto,
  UpdateDealDto,
} from './dto';

@Controller('deals')
export class DealController {
  constructor(private readonly dealService: DealService) {}

  @Post()
  async create(@Body() dto: CreateDealDto) {
    return this.dealService.createDeal(dto);
  }

  @Get()
  findAll(@Query() query: DealListQueryDto) {
    return this.dealService.getDeals(query);
  }

  @Get(':id')
  findOne(@Param() params: DealIdParamDto) {
    return this.dealService.getDealById(params.id);
  }

  @Post(':id')
  @HttpCode(HttpStatus.OK)
  update(@Param() params: DealIdParamDto, @Body() dto: UpdateDealDto) {
    return this.dealService.updateDeal(params.id, dto);
  }

  @Post(':id/stage')
  @HttpCode(HttpStatus.OK)
  transitionStage(
    @Param() params: DealIdParamDto,
    @Body() dto: TransitionDealStageDto,
  ) {
    return this.dealService.transitionDealStage(params.id, dto);
  }
}

