115	    if (Object.keys(dto).length === 0) {
116	      throw this.createValidationException(
117	        'body',
118	        'At least one mutable field is required.',
119	      );
120	    }
121	
122	    const deal = await this.getExistingDeal(id);
123	    const existingLinks = await this.dealContactLinkRepository.findByDealId(id);
124	
125	    const hasIncomingLinks = dto.contactLinks !== undefined;
126	    const normalizedLinks = hasIncomingLinks
127	      ? this.normalizeContactLinks(dto.contactLinks ?? [])
128	      : existingLinks;
129	
130	    if (hasIncomingLinks) {
131	      await this.ensureContactsExist(
132	        normalizedLinks.map((link) => link.contactId),
133	      );
134	    }
135	
136	    const resolvedPrimaryContactId = this.resolvePrimaryContactId({
137	      links: normalizedLinks,
138	      preferredPrimaryContactId:
139	        dto.primaryContactId === undefined ? undefined : dto.primaryContactId,
140	      fallbackPrimaryContactId: deal.primaryContactId,
141	    });
142	
143	    this.ensurePrimaryContactInLinks(resolvedPrimaryContactId, normalizedLinks);
144	
145	    const stageTransition =
146	      dto.stage === undefined
147	        ? undefined
148	        : this.resolveStageTransition({
149	            currentStage: normalizeStoredDealStage(deal.stage),
150	            requestedStageValue: dto.stage,
151	            linkedContactCount: normalizedLinks.length,
152	            expectedCloseDate:
