154	                ? deal.expectedCloseDate
155	                : dto.expectedCloseDate,
156	          });
157	
158	    await this.dealRepository.manager.transaction(async (manager) => {
159	      const mergedDeal = manager.getRepository(DealEntity).merge(deal, {
160	        name: dto.name,
161	        value: dto.value,
162	        stage:
163	          stageTransition?.shouldPersist === true
164	            ? stageTransition.targetStage
165	            : undefined,
166	        expectedCloseDate: dto.expectedCloseDate,
167	        primaryContactId: resolvedPrimaryContactId,
168	      });
169	
170	      await manager.getRepository(DealEntity).save(mergedDeal);
171	
172	      if (hasIncomingLinks) {
173	        await manager
174	          .getRepository(DealContactLinkEntity)
175	          .delete({ dealId: id });
176	
177	        if (normalizedLinks.length > 0) {
178	          await manager.getRepository(DealContactLinkEntity).save(
179	            normalizedLinks.map((link) =>
180	              manager.getRepository(DealContactLinkEntity).create({
181	                dealId: id,
182	                contactId: link.contactId,
183	                role: link.role ?? null,
184	              }),
185	            ),
186	          );
187	        }
188	      }
189	    });
190	
191	    return this.getDealWithLinks(id, false);
