392	  private resolveInitialStage(stageValue: string | undefined): DealStage {
393	    if (stageValue === undefined) {
394	      return 'lead';
395	    }
396	
397	    const parsedStage = this.parseRequestedStageOrThrow(stageValue);
398	
399	    if (!DEAL_INITIAL_STAGES.includes(parsedStage)) {
400	      throw new AppException({
401	        statusCode: HttpStatus.BAD_REQUEST,
402	        code: BUSINESS_ERROR_CODES.INVALID_INITIAL_STAGE,
403	        message: 'Initial stage must be either lead or qualified.',
404	        details: {
405	          stage: parsedStage,
406	          allowedInitialStages: DEAL_INITIAL_STAGES,
407	        },
408	      });
409	    }
410	
411	    return parsedStage;
412	  }
