414	  private resolveStageTransition({
415	    currentStage,
416	    requestedStageValue,
417	    linkedContactCount,
418	    expectedCloseDate,
419	  }: {
420	    currentStage: DealStage;
421	    requestedStageValue: string;
422	    linkedContactCount: number;
423	    expectedCloseDate: string | null;
424	  }): StageTransitionResult {
425	    const targetStage = this.parseRequestedStageOrThrow(requestedStageValue);
426	
427	    if (targetStage === currentStage) {
428	      return {
429	        targetStage,
430	        shouldPersist: false,
431	      };
432	    }
433	
434	    const allowedTargets = DEAL_STAGE_TRANSITIONS[currentStage];
435	
436	    if (!allowedTargets.includes(targetStage)) {
437	      throw new AppException({
438	        statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
439	        code: BUSINESS_ERROR_CODES.INVALID_STAGE_TRANSITION,
440	        message: `Cannot move deal from ${currentStage} to ${targetStage}.`,
441	        details: {
442	          currentStage,
443	          targetStage,
444	          allowedTargetStages: allowedTargets,
445	        },
446	      });
447	    }
448	
449	    if (targetStage === 'active' && linkedContactCount < 1) {
450	      throw new AppException({
451	        statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
452	        code: BUSINESS_ERROR_CODES.TRANSITION_PRECONDITION_UNMET,
453	        message: 'Transition to active requires at least one linked contact.',
454	        details: {
455	          targetStage,
456	          required: 'linked_contact',
457	        },
458	      });
459	    }
460	
461	    if (targetStage === 'negotiation' && !expectedCloseDate) {
462	      throw new AppException({
463	        statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
464	        code: BUSINESS_ERROR_CODES.TRANSITION_PRECONDITION_UNMET,
465	        message: 'Transition to negotiation requires an expected close date.',
466	        details: {
467	          targetStage,
468	          required: 'expected_close_date',
469	        },
470	      });
471	    }
472	
473	    return {
474	      targetStage,
475	      shouldPersist: true,
476	    };
477	  }
478	
479	  private parseRequestedStageOrThrow(stageValue: string): DealStage {
480	    const parsedStage = parseRequestedDealStage(stageValue);
481	
482	    if (!parsedStage) {
483	      throw new AppException({
484	        statusCode: HttpStatus.BAD_REQUEST,
485	        code: BUSINESS_ERROR_CODES.UNKNOWN_STAGE,
486	        message: `Unknown stage: ${stageValue}`,
487	        details: {
488	          stage: stageValue,
489	        },
490	      });
491	    }
492	
493	    return parsedStage;
494	  }
495	}

