 21	const STAGE_TRANSITIONS = {
 22	  lead: ['qualified', 'closed_lost'],
 23	  qualified: ['active', 'closed_lost'],
 24	  active: ['negotiation', 'closed_lost'],
 25	  negotiation: ['closed_won', 'closed_lost'],
 26	  closed_won: [],
 27	  closed_lost: ['lead'],
 28	};
