 30	const STAGE_SET = new Set(DEAL_STAGES);
 31	
 32	export function normalizeStage(stage) {
 33	  const normalized = typeof stage === 'string' ? stage.trim().toLowerCase() : '';
 34	
 35	  return STAGE_SET.has(normalized) ? normalized : 'lead';
 36	}
