 42	export function getTransitionOptions({ currentStage, hasLinkedContacts }) {
 43	  const normalizedCurrentStage = normalizeStage(currentStage);
 44	  const allowedTargets = STAGE_TRANSITIONS[normalizedCurrentStage] ?? [];
 45	
 46	  return allowedTargets.filter((targetStage) => {
 47	    if (targetStage === 'active' && !hasLinkedContacts) {
 48	      return false;
 49	    }
 50	
 51	    return true;
 52	  });
 53	}
