 8	import { Request, Response } from 'express';
 9	import { AppExceptionPayload } from '../errors/app-exception';
10	import { BUSINESS_ERROR_CODES } from '../errors/error-codes';
11	
12	type ExceptionResponsePayload = {
13	  code?: string;
14	  message?: string | string[];
15	  details?: unknown;
16	};
17	
18	const isExceptionResponsePayload = (
19	  value: unknown,
20	): value is ExceptionResponsePayload => {
21	  return typeof value === 'object' && value !== null;
22	};
