24	@Catch(HttpException)
25	export class HttpExceptionFilter implements ExceptionFilter {
26	  catch(exception: HttpException, host: ArgumentsHost) {
27	    const ctx = host.switchToHttp();
28	    const response = ctx.getResponse<Response>();
29	    const request = ctx.getRequest<Request>();
30	
31	    // Get the HTTP status code from the exception (e.g., 400, 404, 500)
32	    const status = exception.getStatus();
33	
34	    // Get the detailed response content from the exception
35	    const exceptionResponse: unknown = exception.getResponse();
36	    const payload = isExceptionResponsePayload(exceptionResponse)
37	      ? exceptionResponse
38	      : undefined;
39	
40	    // Extract error message
41	    const message = payload?.message ? payload.message : exception.message;
42	    const normalizedMessage = Array.isArray(message) ? message[0] : message;
43	    const code = payload?.code ?? defaultErrorCode(status);
44	    const details = payload?.details;
45	
46	    response.status(status).json({
47	      success: false,
48	      statusCode: status,
49	      code,
50	      message: normalizedMessage,
51	      details,
52	      timestamp: new Date().toISOString(),
53	      path: request.url,
54	    });
55	  }
56	}
