58	function defaultErrorCode(status: number): AppExceptionPayload['code'] {
59	  const errorCodeByStatus: Partial<
60	    Record<number, AppExceptionPayload['code']>
61	  > = {
62	    [HttpStatus.BAD_REQUEST]: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
63	    [HttpStatus.NOT_FOUND]: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
64	    [HttpStatus.UNPROCESSABLE_ENTITY]: BUSINESS_ERROR_CODES.IMMUTABLE_FIELD,
65	    [HttpStatus.CONFLICT]: BUSINESS_ERROR_CODES.REFERENTIAL_INTEGRITY_VIOLATION,
66	  };
67	
68	  return errorCodeByStatus[status] ?? BUSINESS_ERROR_CODES.VALIDATION_ERROR;
69	}
