 2	import { AppException } from './app-exception';
 3	import { BUSINESS_ERROR_CODES } from './error-codes';
 4	
 5	type FormattedValidationError = {
 6	  field: string;
 7	  messages: string[];
 8	};
 9	
10	export function createValidationException(errors: ValidationError[]) {
11	  const formattedErrors = flattenValidationErrors(errors);
12	  const firstMessage =
13	    formattedErrors[0]?.messages[0] ?? 'Request validation failed.';
14	
15	  return new AppException({
16	    statusCode: HttpStatus.BAD_REQUEST,
17	    code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
18	    message: firstMessage,
19	    details: {
20	      errors: formattedErrors,
21	    },
22	  });
23	}
24	
25	function flattenValidationErrors(
26	  errors: ValidationError[],
27	  parentPath?: string,
28	): FormattedValidationError[] {
29	  return errors.flatMap((error) => {
30	    const field = parentPath
31	      ? `${parentPath}.${error.property}`
32	      : error.property;
33	    const messages = error.constraints ? Object.values(error.constraints) : [];
34	    const currentError = messages.length > 0 ? [{ field, messages }] : [];
35	    const childErrors = error.children
36	      ? flattenValidationErrors(error.children, field)
37	      : [];
38	
39	    return [...currentError, ...childErrors];
40	  });
41	}

