 20	@Injectable()
 21	export class ContactService {
 22	  constructor(
 23	    private readonly contactRepository: ContactRepository,
 24	    private readonly contactCompanyLinkRepository: ContactCompanyLinkRepository,
 25	    private readonly companyService: CompanyService,
