 27	
 28	  async createContact(dto: CreateContactDto): Promise<ContactEntity> {
 29	    this.validateCompanyLinks(
 30	      dto.companies,
 31	      'companies',
 32	      'Contact must include one or more companies with exactly one primary company.',
 33	    );
 34	
 35	    await this.ensureCompaniesExist(dto.companies.map((company) => company.id));
 36	
 37	    const { companies, ...contactPayload } = dto;
 38	
 39	    const createdContact = await this.contactRepository.manager.transaction(
 40	      async (manager) => {
 41	        const contact = await manager
 42	          .getRepository(ContactEntity)
 43	          .save(manager.getRepository(ContactEntity).create(contactPayload));
 44	
 45	        await manager.getRepository(ContactCompanyLinkEntity).save(
 46	          companies.map((company) =>
 47	            manager.getRepository(ContactCompanyLinkEntity).create({
 48	              contactId: contact.id,
 49	              companyId: company.id,
 50	              isPrimary: company.isPrimary,
 51	            }),
 52	          ),
 53	        );
 54	
 55	        return contact;
 56	      },
 57	    );
 58	
 59	    return this.getContactById(createdContact.id);
 60	  }
 61	
 62	  async getContactsList(query: ContactListQueryDto) {
 63	    const [items, total] = await this.contactRepository.findWithFilter(query);
 64	    const hydratedItems = await this.hydrateContacts(items);
 65	
 66	    const pageSize = query.pageSize ?? 20;
 67	    const page = query.page ?? 1;
 68	
 69	    return {
 70	      items: hydratedItems,
 71	      total,
 72	      page,
 73	      pageSize,
 74	      totalPages: Math.ceil(total / pageSize),
 75	    };
 76	  }
 77	
 78	  async getContactById(id: string): Promise<ContactEntity> {
 79	    const contact = await this.getExistingContactEntity(id);
 80	    const hydratedContacts = await this.hydrateContacts([contact]);
 81	
 82	    return hydratedContacts[0];
 83	  }
 84	
 85	  async updateContact(
 86	    id: string,
 87	    dto: UpdateContactDto,
 88	  ): Promise<ContactEntity> {
 89	    const contact = await this.getExistingContactEntity(id);
 90	
 91	    if (dto.companies) {
 92	      this.validateCompanyLinks(
 93	        dto.companies,
 94	        'companies',
 95	        'Contact must include one or more companies with exactly one primary company.',
 96	      );
 97	
 98	      await this.ensureCompaniesExist(
 99	        dto.companies.map((company) => company.id),
100	      );
101	
102	      const existingLinks =
103	        await this.contactCompanyLinkRepository.findLinksByContactId(id);
104	      this.ensurePrimaryLinkStateForReplacement(existingLinks, dto.companies);
105	
106	      const { companies, ...contactPayload } = dto;
107	
108	      await this.contactRepository.manager.transaction(async (manager) => {
109	        const mergedContact = manager
110	          .getRepository(ContactEntity)
111	          .merge(contact, contactPayload);
112	
113	        await manager.getRepository(ContactEntity).save(mergedContact);
114	
115	        await manager
116	          .getRepository(ContactCompanyLinkEntity)
117	          .delete({ contactId: id });
118	
119	        await manager.getRepository(ContactCompanyLinkEntity).save(
120	          companies.map((company) =>
121	            manager.getRepository(ContactCompanyLinkEntity).create({
122	              contactId: id,
123	              companyId: company.id,
124	              isPrimary: company.isPrimary,
125	            }),
126	          ),
127	        );
128	      });
129	
130	      return this.getContactById(id);
131	    }
132	
133	    const updatedContact = this.contactRepository.merge(contact, dto);
134	    await this.contactRepository.save(updatedContact);
135	
136	    return this.getContactById(id);
137	  }
