139	  async removeContact(id: string): Promise<void> {
140	    await this.getExistingContactEntity(id);
141	    await this.contactRepository.softDelete(id);
142	  }
143	
144	  private async hydrateContacts(contacts: ContactEntity[]) {
145	    if (contacts.length === 0) {
146	      return [];
147	    }
148	
149	    const companyMap =
150	      await this.contactCompanyLinkRepository.findCompanySummariesByContactIds(
151	        contacts.map((contact) => contact.id),
152	      );
153	
154	    return contacts.map((contact) => ({
155	      ...contact,
156	      companies: this.sortCompanies(companyMap.get(contact.id) ?? []),
157	    }));
158	  }
159	
160	  private sortCompanies(companies: ContactCompanySummary[]) {
161	    return [...companies].sort((left, right) => {
162	      if (left.isPrimary === right.isPrimary) {
163	        return left.name.localeCompare(right.name);
164	      }
165	
166	      return left.isPrimary ? -1 : 1;
167	    });
168	  }
169	
170	  private async ensureCompaniesExist(companyIds: string[]) {
171	    for (const companyId of companyIds) {
172	      try {
173	        await this.companyService.getCompanyById(companyId);
174	      } catch (error) {
175	        if (this.isNotFoundException(error)) {
176	          throw new AppException({
177	            statusCode: HttpStatus.NOT_FOUND,
178	            code: BUSINESS_ERROR_CODES.NOT_FOUND,
179	            message: `Company with ID ${companyId} not found`,
180	            details: {
181	              resource: 'Company',
182	              id: companyId,
183	            },
184	          });
185	        }
186	
187	        throw error;
188	      }
189	    }
190	  }
191	
192	  private validateCompanyLinks(
193	    companies:
194	      ContactCompanyLinkInputDto[] | UpdateContactCompanyLinkInputDto[],
195	    field: string,
196	    message: string,
197	  ) {
198	    if (companies.length === 0) {
199	      throw this.createValidationException(field, message);
200	    }
201	
202	    const primaryCount = companies.filter(
203	      (company) => company.isPrimary,
204	    ).length;
205	
206	    if (primaryCount !== 1) {
207	      throw this.createValidationException(field, message);
208	    }
209	
210	    const uniqueCompanyIds = new Set(companies.map((company) => company.id));
211	
212	    if (uniqueCompanyIds.size !== companies.length) {
213	      throw this.createValidationException(
214	        field,
215	        'Duplicate company links are not allowed.',
216	      );
217	    }
218	  }
219	
220	  private ensurePrimaryLinkStateForReplacement(
221	    existingLinks: ContactCompanyLinkEntity[],
222	    nextLinks: UpdateContactCompanyLinkInputDto[],
223	  ) {
224	    const existingPrimary = existingLinks.find((link) => link.isPrimary);
225	
226	    if (!existingPrimary) {
227	      return;
228	    }
229	
230	    const nextPrimary = nextLinks.find((link) => link.isPrimary);
231	
232	    if (!nextPrimary) {
233	      return;
234	    }
235	
236	    if (nextPrimary.id === existingPrimary.companyId) {
237	      return;
238	    }
239	
240	    const nextLinkCompanyIds = new Set(nextLinks.map((link) => link.id));
241	
242	    if (nextLinkCompanyIds.has(existingPrimary.companyId)) {
243	      return;
244	    }
245	
246	    const existingCompanyIds = new Set(
247	      existingLinks.map((link) => link.companyId),
248	    );
249	
250	    if (!existingCompanyIds.has(nextPrimary.id)) {
251	      throw new AppException({
252	        statusCode: HttpStatus.CONFLICT,
253	        code: BUSINESS_ERROR_CODES.INVALID_LINK_STATE,
254	        message:
255	          'Primary company cannot be detached unless another existing linked company becomes primary in the same operation.',
256	        details: {
257	          contactId: existingPrimary.contactId,
258	          primaryCompanyId: existingPrimary.companyId,
259	          nextPrimaryCompanyId: nextPrimary.id,
260	        },
261	      });
262	    }
263	  }
264	
265	  private async getExistingContactEntity(id: string) {
266	    const contact = await this.contactRepository.findOne({ where: { id } });
267	
268	    if (!contact) {
269	      throw new AppException({
270	        statusCode: HttpStatus.NOT_FOUND,
271	        code: BUSINESS_ERROR_CODES.NOT_FOUND,
272	        message: `Contact with ID ${id} not found`,
273	        details: {
274	          resource: 'Contact',
275	          id,
276	        },
277	      });
278	    }
279	
280	    return contact;
281	  }
282	
283	  private createValidationException(field: string, message: string) {
284	    return new AppException({
285	      statusCode: HttpStatus.BAD_REQUEST,
286	      code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
287	      message,
288	      details: {
289	        errors: [
290	          {
291	            field,
292	            messages: [message],
293	          },
294	        ],
295	      },
296	    });
297	  }
298	
299	  private isNotFoundException(error: unknown): boolean {
300	    return (
301	      error instanceof AppException &&
302	      error.getStatus() === HttpStatus.NOT_FOUND
303	    );
304	  }
305	}
