  3	import { BaseRepository } from '../../core/database/base.repository';
  4	import { ContactEntity } from './contact.entity';
  5	import { ContactListQueryDto } from './dto';
  6	import { ContactCompanyLinkEntity } from './contact-company-link.entity';
  7	
  8	@Injectable()
  9	export class ContactRepository extends BaseRepository<ContactEntity> {
 10	  constructor(dataSource: DataSource) {
 11	    super(ContactEntity, dataSource.createEntityManager());
 12	  }
 13	
 14	  async findWithFilter(query: ContactListQueryDto) {
 15	    const queryBuilder = this.createQueryBuilder('contact');
 16	
 17	    const sortField = query.sort
 18	      ? `contact.${query.sort}`
 19	      : 'contact.createdAt';
 20	    const sortOrder = query.order ? query.order.toUpperCase() : 'DESC';
 21	    queryBuilder.orderBy(sortField, sortOrder as 'ASC' | 'DESC');
 22	
 23	    if (query.companyId) {
 24	      queryBuilder.andWhere((subQuery) => {
 25	        const existsQuery = subQuery
 26	          .subQuery()
 27	          .select('1')
 28	          .from(ContactCompanyLinkEntity, 'contactCompanyLink')
 29	          .where('contactCompanyLink."contactId" = contact.id')
 30	          .andWhere('contactCompanyLink."companyId" = :companyId')
 31	          .getQuery();
 32	
 33	        return `EXISTS ${existsQuery}`;
 34	      });
 35	      queryBuilder.setParameter('companyId', query.companyId);
 36	    }
 37	
 38	    if (query.q) {
 39	      const searchValue = `%${query.q}%`;
 40	      queryBuilder.andWhere(
 41	        new Brackets((qb) => {
 42	          qb.where('contact.name ILIKE :searchValue', { searchValue })
 43	            .orWhere('contact.email ILIKE :searchValue', { searchValue })
 44	            .orWhere('contact.phone ILIKE :searchValue', { searchValue })
 45	            .orWhere('contact.role ILIKE :searchValue', { searchValue });
 46	        }),
 47	      );
 48	    }
 49	
 50	    if (query.role) {
 51	      queryBuilder.andWhere('contact.role = :role', { role: query.role });
 52	    }
 53	
 54	    const offset = query.offset ?? 0;
 55	    const limit = query.limit ?? 20;
 56	
 57	    return queryBuilder.skip(offset).take(limit).getManyAndCount();
 58	  }
 59	}
