26	      .addSelect('company.id', 'companyId')
27	      .addSelect('company.name', 'companyName')
28	      .addSelect('link.isPrimary', 'isPrimary')
29	      .where('link.contactId IN (:...contactIds)', { contactIds })
30	      .orderBy('link.isPrimary', 'DESC')
31	      .addOrderBy('company.name', 'ASC')
32	      .getRawMany<{
33	        contactId: string;
34	        companyId: string;
35	        companyName: string;
36	        isPrimary: boolean;
37	      }>();
38	
39	    const map = new Map<string, ContactCompanySummary[]>();
40	
41	    for (const row of rows) {
42	      const existing = map.get(row.contactId) ?? [];
43	      existing.push({
44	        id: row.companyId,
45	        name: row.companyName,
46	        isPrimary: row.isPrimary,
47	      });
48	      map.set(row.contactId, existing);
49	    }
50	
51	    return map;
