10	
11	const logger = new Logger('Seed');
12	
13	const scenarios: Record<SeedScenarioName, SeedScenario> = {
14	  demo: demoSeedScenario,
15	  'edge-case': edgeCaseSeedScenario,
16	};
17	
18	const parseArgs = (argv: string[]) => {
19	  const scenarioName = (argv[0] ?? 'demo') as SeedScenarioName;
20	  const shouldReset = argv.includes('--reset');
21	
22	  if (!(scenarioName in scenarios)) {
23	    throw new Error(
24	      `Unknown seed scenario "${scenarioName}". Use one of: ${Object.keys(scenarios).join(', ')}`,
25	    );
26	  }
27	
28	  return {
29	    scenarioName,
30	    shouldReset,
31	  };
32	};
33	
34	const run = async () => {
35	  const { scenarioName, shouldReset } = parseArgs(process.argv.slice(2));
36	  const app = await NestFactory.createApplicationContext(AppModule, {
37	    logger: ['error', 'warn', 'log'],
38	  });
39	
40	  try {
41	    const dataSource = app.get(DataSource);
42	
43	    if (shouldReset) {
44	      await resetSeedTables({ dataSource, now: new Date() });
45	      logger.log('Reset deals, contacts, companies, and link tables.');
